5	export default function VideoBackground({ onEarlyEnd, onEnded, IntroVideo }) {
6	  const videoRef = useRef(null);
7	  const timeoutRef = useRef(null);
8	
9	
10	  const handleLoadedMetadata = () => {
11	    const video = videoRef.current;
12	    if (!video) return;
13	
14	    const advance = 0.1; // ~5 frame
15	    const triggerTime = Math.max(video.duration - advance, 0) * 1000;
16	
17	    timeoutRef.current = setTimeout(() => {
18	      if (onEarlyEnd) onEarlyEnd();
19	    }, triggerTime);
20	  };
21	  const closeVideo = () => {
22	    const v = videoRef.current;
23	    if (!v) return;
24	    if (timeoutRef.current) {
25	      clearTimeout(timeoutRef.current);
26	      timeoutRef.current = null;
27	    }
28	    v.pause();
29	    v.src = "";
30	    v.load();
31	    if (onEnded) onEnded(); 
32	  };
33	
34	  const SkipIntro = () => {
35	    closeVideo();
36	    if (onEarlyEnd) onEarlyEnd();
37	  };
38	
39	  return (
40	    <div>
41	    <div
42	      onClick={SkipIntro}
43	      style={{
44	        position: "fixed",
45	        top: 0,
46	        left: 0,
47	        width: "100vw",
48	        height: "100vh",
49	
50	        backgroundColor: "transparent",
51	
52	        zIndex: 9999,
53	        display: "flex",
54	        justifyContent: "center",
55	        alignItems: "center",
56	      }}
57	    ></div>
58	      <video
59	        ref={videoRef}
60	        src={`${IntroVideo}`}
61	        autoPlay
62	        style={{
63	          position: "fixed",
64	          top: 0,
65	          left: 0,
66	          width: "100vw",
67	          height: "100vh",
68	          objectFit: "cover",
69	          zIndex: -1,
70	          
71	        }}
72	        onLoadedMetadata={handleLoadedMetadata} // chắc chắn duration đã sẵn sàng
73	        onEnded={onEnded}                       // video kết thúc thật
74	      />
75	    </div>
76	  );
77	}
