6	export function handleButtonClick(times, list, guarantee) {
7	  // rollByRate nằm trong đây luôn
8	  const rollByRate = (rateDict) => {
9	    const rand = Math.random();
10	    let cumulative = 0;
11	
12	    for (const key in rateDict) {
13	      cumulative += rateDict[key];
14	      if (rand <= cumulative) return key;
15	    }
16	
17	    return Object.keys(rateDict).slice(-1)[0];
18	  };
19	
20	  let result = {};
21	  let gua_result = {};
22	  let total = 0;
23	  let missingKey = null;
24	  let missingKey_er = null;
25	
26	  // =====================
27	  // LIST (fallback nếu list == null)
28	  // =====================
29	  if (list) { // fallback: nếu list null/false thì bỏ qua
30	    list.forEach(item => {
31	      if (item.includes("~")) {
32	        const [key, valStr] = item.split("~").map(s => s.trim());
33	        const value = parseFloat(valStr.replace("%", "")) / 100;
34	        result[key] = value;
35	        total += value;
36	      } else {
37	        missingKey = item.trim();
38	      }
39	    });
40	
41	    if (missingKey) {
42	      result[missingKey] = 1 - total;
43	    }
44	  }
45	
46	  // =====================
47	  // GUARANTEE (fallback nếu guarantee == null)
48	  // =====================
49	  if (guarantee) { // fallback: nếu guarantee null/false thì bỏ qua
50	    guarantee.forEach(item => {
51	      if (item.includes("~")) {
52	        const [key, valStr] = item.split("~").map(s => s.trim());
53	        const value = parseFloat(valStr.replace("%", "")) / 100;
54	        gua_result[key] = value;
55	        total += value;
56	      } else {
57	        missingKey_er = item.trim();
58	      }
59	    });
60	
61	    if (missingKey_er) {
62	      gua_result[missingKey_er] = 1 - total;
63	    }
64	  }
65	
66	  let gachas_ed = [];
67	  let gacha = [];
68	
69	  // =====================
70	  // Roll theo list (chỉ khi list tồn tại)
71	  // =====================
72	  if (list) { // fallback
73	    for (let i = 0; i < times; i++) {
74	      gachas_ed.push(rollByRate(result));
75	    }
76	  }
77	
78	  // =====================
79	  // Roll guarantee (chỉ khi guarantee tồn tại)
80	  // =====================
81	  if (guarantee) { // fallback
82	    gachas_ed.push(rollByRate(gua_result));
83	  }
84	
85	  // =====================
86	  // Xử lý các lựa chọn ngẫu nhiên ("|")
87	  // =====================
88	  gachas_ed.forEach(item => {
89	    if (item.includes("|")) {
90	      const choices = item.split("|").map(s => s.trim());
91	      const randomChoice = choices[Math.floor(Math.random() * choices.length)];
92	      gacha.push(randomChoice);
93	    } else {
94	      gacha.push(item);
95	    }
96	  });
97	
98	  // --- BỔ SUNG: TẠO ARRAY MỚI VÀ XỬ LÝ GROUP ---
99	  let gachaWithGroup = [];
100	  gacha.forEach((item, k) => {
101	    // Logic Group
102	    if (item.includes("...")) {
103	      // Lấy A và B từ "A...B"
104	      const rangeMatch = item.match(/(\d+)\.\.\.(\d+)/);
105	      if (rangeMatch) {
106	        const A = parseInt(rangeMatch[1], 10);
107	        const B = parseInt(rangeMatch[2], 10);
108	        const C = getRandomInt(A, B);
109	        gacha[k] = item.replace(`${A}...${B}`, C); // thay "A...B" bằng "C"
110	      }
111	    }
112	
113	    const match = gacha[k].match(/^(\d+)?\s*(\D*)$/);
114	    let groupKey = match[2] ? match[2].trim() : "Task";
115	
116	    gachaWithGroup.push(`${gacha[k]} ~ ${groupKey}`);
117	  });
118	  // --- KẾT THÚC BỔ SUNG ---
119	
120	  let i = 0;
121	  gachaWithGroup.forEach(rawitem => {
122	    const item = rawitem.split("~")[0].trim();
123	    let NewGroup = rawitem.split("~")[1];
124	    NewGroup = NewGroup.split("/").pop().split(".")[0].trim();
125	
126	    if (item.includes("File: ")) {
127	      const match = item.match(/File:\s*(.*)/);
