130	        card_file["Hazard"][Math.floor(Math.random() * card_file["Hazard"].length)];
131	
132	      gachaWithGroup[i] = `${chosen_filecard["Tag"]} ~ ${NewGroup}`;
133	    }
134	    i++;
135	  });
136	
137	  let all_gacha = {};
138	
139	  // =====================
140	  // Tổng hợp kết quả
141	  // =====================
142	  gachaWithGroup.forEach(item => {
143	    const match = item.match(/^(.*?)\s*~\s*(.*)$/); // tách theo dấu ~
144	    let num = 1;
145	
146	    if (match[1]) {
147	      const numMatch = match[1].match(/^\d+/);
148	      if (numMatch) {
