3	// Custom hook: lấy danh sách card pack từ file JSON local
4	export default function useCardpacks() {
5	  const [cardpacks, setCardpacks] = useState([]);
6	  const [loading, setLoading] = useState(true);
7	  const [error, setError] = useState(null);
8	
9	  useEffect(() => {
10	    // ⚠️ THAY "cardpacks.json" bằng đúng tên file JSON của bạn
11	    const jsonUrl = new URL("./Decks.json", import.meta.url);
12	
13	    fetch(jsonUrl)
14	      .then((res) => {
15	        if (!res.ok) {
16	          // Báo lỗi HTTP rõ ràng
17	          throw new Error("Failed to load local cardpacks JSON");
18	        }
19	        return res.json();
20	      })
21	      .then((data) => {
22	        setCardpacks(data);
23	        setLoading(false);
24	      })
25	      .catch((err) => {
26	        console.error(err);
27	        setError(err);
28	        setLoading(false);
29	      });
30	  }, []); 
31	  // Không còn backendUrl → dependency rỗng là đúng
32	
33	  return {
34	    cardpacks,
35	    loading,
36	    error,
37	  };
38	}
